shopify_product_graphql_mutation_payload.graphql_mutation:
mutation CreateRashguardProductWithVariants($input: ProductInput!) {
  productCreate(input: $input) {
    product {
      id
      title
      handle
      status
      totalVariants
      variants(first: 50) {
        edges {
          node {
            id
            title
            sku
            barcode
            price
          }
        }
      }
    }
    userErrors {
      field
      message
    }
  }
}

egress_shipment_webhook_handler.shopify_graphql_mutation:
mutation FulfillmentCreateV2($fulfillment: FulfillmentV2Input!) {
  fulfillmentCreateV2(fulfillment: $fulfillment) {
    fulfillment {
      id
      status
      trackingInfo {
        company
        number
        url
      }
    }
    userErrors {
      field
      message
    }
  }
}
